// Monolithic approach: Direct service call
public void processOrder(Order order) {
    inventoryService.reserve(order.getItems()); // In-memory call
    paymentService.charge(order.getAmount());    // Transactional context shared
}

// Microservices approach: Event-driven choreography
public void processOrder(Order order) {
    // Publish event to Kafka/RabbitMQ to decouple services
    eventPublisher.publish(new OrderCreatedEvent(order)); 
    // Inventory and Payment services consume independently
}
